    private static readonly (string From, string En, string Tw)[] Longest = Phrases.OrderByDescending(p => p.Simplified.Length).Select(p => (p.Simplified, p.English, p.Traditional)).ToArray();
    internal static string Text(string value)
    {
        string probe = Loc.T("en", "zh-cn", "zh-tw");
        if (probe == "zh-cn") return value;
        bool english = probe == "en";
        foreach (var pair in Longest) value = value.Replace(pair.From, english ? pair.En : pair.Tw);
        return value;
    }
    internal static string Script(string source) => Text(source);
